from pathlib import Path
import base64

path = Path(r"D:\Het\demo2\static\js\page3.js")
text = path.read_text(encoding="utf-8")

old = base64.b64decode("").decode("utf-8")
new = base64.b64decode("").decode("utf-8")

count = text.count(old)
if count != 1:
    raise SystemExit(
        f"FAIL - expected operator search-action block exactly once, found {count}"
    )

text = text.replace(old, new, 1)

for token in (
    "OPERATOR_SEARCH_ACTION_FIX_V1",
    "openOperatorCompleteModal(globalIdx);",
    "This Job Card is not active in your assigned operator queue.",
):
    if token not in text:
        raise SystemExit(f"FAIL - missing verification token: {token}")

path.write_text(text, encoding="utf-8")

print("PASS - operator search action no longer depends on myAccessibleProcesses")
print("PASS - searched JC resolves against the operator assigned queue")
print("PASS - process/item matching added with JC fallback")
print("PASS - no backend or database change executed")
